package com.gathin.tvhome;
import android.app.*;import android.content.*;import android.content.pm.*;import java.io.*;import java.util.*;
/** Remaining basic launcher choices, presented through the same preview and settings cards. */
final class LauncherBehaviorPopup {
 static void show(MainActivity a){android.content.SharedPreferences p=a.getSharedPreferences(Config.SETTINGS_NAME,0);Config cfg=Config.load(a);SettingsSheet s=new SettingsSheet(a,"Launcher-Verhalten");
  final android.widget.LinearLayout[] toggles=new android.widget.LinearLayout[2];toggles[0]=s.toggle("Animationen",null,cfg.animations,on->{android.content.SharedPreferences.Editor e=p.edit().putBoolean("animations",on);if(!on)e.putBoolean("advanced_effects",false);e.apply();if(!on&&toggles[1]!=null)SettingsSheet.syncToggle(toggles[1],false);a.refreshBasicLauncher(false);});
  toggles[1]=s.toggle(a.getString(R.string.advanced_effects),a.getString(R.string.advanced_effects_warning),cfg.advancedEffects,on->{p.edit().putBoolean("advanced_effects",on).putBoolean("animations",on||p.getBoolean("animations",cfg.animations)).apply();if(on)SettingsSheet.syncToggle(toggles[0],true);a.refreshBasicLauncher(false);});
  s.row("photo","Bilder aus dem eigenen Theme","Vorhandene wallpaper.jpg und wallpapers-Dateien",()->wallpapers(a));
  s.row("timer",a.getString(R.string.open_on_start_label),"Home oder eine installierte App beim Start",()->startup(a));
  s.row("settings",a.getString(R.string.follow_theme),"Grundwerte wieder aus dem eigenen Theme übernehmen",()->{p.edit().remove("columns").remove(Config.ROWS_BELOW_DOCK_KEY).remove("animations").remove("advanced_effects").remove(Config.WALLPAPER_CHOICE_KEY).remove(Config.DOCK_OPACITY_KEY).remove(OpenOnStart.KEY).apply();a.refreshBasicLauncher(true);});
  s.show();
 }
 static void wallpapers(MainActivity a){SettingsSheet s=new SettingsSheet(a,"Bilder aus dem eigenen Theme");android.content.SharedPreferences p=a.getSharedPreferences(Config.SETTINGS_NAME,0);File dir=Config.dir(a);List<File> images=new ArrayList<>(WallpaperRotation.images(dir==null?null:new File(dir,"wallpapers")));File single=dir==null?null:new File(dir,Config.WALLPAPER_NAME);if(single!=null&&single.isFile())images.add(0,single);
  s.choice("photo",a.getString(R.string.wallpaper_theme_default),null,()->!p.contains(Config.WALLPAPER_CHOICE_KEY),()->{p.edit().remove(Config.WALLPAPER_CHOICE_KEY).apply();HomeBackdrop.select(a,"original","0");a.refreshBasicLauncher(true);});s.choice("photo",a.getString(R.string.wallpaper_none),null,()->"none".equals(p.getString(Config.WALLPAPER_CHOICE_KEY,"")),()->{p.edit().putString(Config.WALLPAPER_CHOICE_KEY,"none").apply();HomeBackdrop.select(a,"original","0");a.refreshBasicLauncher(true);});for(File f:images)s.choice("photo",f.getName(),null,()->f.getName().equals(p.getString(Config.WALLPAPER_CHOICE_KEY,"")),()->{p.edit().putString(Config.WALLPAPER_CHOICE_KEY,f.getName()).apply();HomeBackdrop.select(a,"original","0");a.refreshBasicLauncher(true);});if(images.isEmpty())s.info("Im eigenen Theme sind noch keine zusätzlichen Bilddateien vorhanden.");s.show();}
 private static void startup(MainActivity a){SettingsSheet s=new SettingsSheet(a,a.getString(R.string.open_on_start_label));android.content.SharedPreferences p=a.getSharedPreferences(Config.SETTINGS_NAME,0);s.choice("tv","Home",null,()->p.getString(OpenOnStart.KEY,"").isEmpty(),()->p.edit().remove(OpenOnStart.KEY).apply());List<ResolveInfo> apps=a.getPackageManager().queryIntentActivities(new Intent(Intent.ACTION_MAIN).addCategory(Intent.CATEGORY_LEANBACK_LAUNCHER),0);apps.sort((x,y)->String.valueOf(x.loadLabel(a.getPackageManager())).compareToIgnoreCase(String.valueOf(y.loadLabel(a.getPackageManager()))));Set<String> seen=new HashSet<>();for(ResolveInfo r:apps){String pkg=r.activityInfo.packageName;if(pkg.equals(a.getPackageName())||!seen.add(pkg))continue;s.choice("grid",String.valueOf(r.loadLabel(a.getPackageManager())),null,()->pkg.equals(p.getString(OpenOnStart.KEY,"")),()->{OpenOnStart.skipThisBoot(a);p.edit().putString(OpenOnStart.KEY,pkg).apply();});}s.show();}
}
